from lc import L, w, gr, q

B2 = [
 L("Why Every Drop of Water Counts", "為什麼每一滴水都重要", [
   "Although water covers most of our planet, about 97 percent of it is salty seawater. Most of the fresh water is frozen in ice or hidden underground, which leaves only a tiny share that is easy for people to use.",
   "Taiwan gets plenty of rain, but its rivers are short and steep, so much of the water flows quickly into the sea. During a severe drought in 2021, reservoirs fell to very low levels, and some areas had to limit their water supply.",
   "Around the world, farming uses most of the fresh water we take, so saving water is not only about what happens at home. Still, small habits help: take shorter showers, fix dripping taps and reuse water from washing vegetables for your plants."],
  [w("salty","adjective","/ˈsɑːl.ti/","鹹的","containing salt","salty seawater","salt + -y。"),
   w("frozen","adjective","/ˈfroʊ.zən/","結冰的","turned into ice","frozen lakes","freeze 的過去分詞。"),
   w("underground","adverb","/ˌʌn.dɚˈɡraʊnd/","在地下","below the surface of the ground","Water is stored underground.","hidden underground 藏在地底。"),
   w("steep","adjective","/stiːp/","陡峭的","rising or falling sharply","a steep hill","short and steep 短而陡。"),
   w("drought","noun","/draʊt/","乾旱","a long period with little or no rain","a severe drought","a severe drought 嚴重乾旱。"),
   w("reservoir","noun","/ˈrez.ɚ.vwɑːr/","水庫","a lake used to store water for people","The reservoir is almost empty.","reservoirs fell 水庫水位下降。"),
   w("drip","verb","/drɪp/","滴水","to let drops of liquid fall","The tap is dripping.","dripping taps 滴水的水龍頭。")],
  [gr("which leaves…","which 指前句，造成的結果。","which leaves only a tiny share that is easy for people to use"),
   gr("so 表結果","所以…。","its rivers are short and steep, so much of the water flows quickly into the sea"),
   gr("not only about…","不只關於…。","saving water is not only about what happens at home")],
  [q("What share of the Earth's water is salty?","About 97 percent","About half","About 10 percent"),
   q("Why does much of Taiwan's rain flow away quickly?","Its rivers are short and steep","It never rains","The sea is too close to the sky"),
   q("What uses most of the world's fresh water?","Farming","Showers","Swimming pools")]),
 L("Penguins: Birds Built for the Sea", "企鵝：為海洋而生的鳥", [
   "Penguins cannot fly, but they are superb swimmers. Their wings have become stiff flippers, and their smooth, torpedo-shaped bodies help them chase fish and squid underwater. Some species can dive hundreds of meters deep.",
   "There are around 18 kinds of penguin, and almost all of them live in the Southern Hemisphere. Only a few live in Antarctica itself. Others live on the coasts of South America, Africa, Australia and New Zealand, and one species even lives near the equator in the Galápagos Islands.",
   "Emperor penguins have one of the toughest lives on Earth. The males keep the egg warm on their feet through the dark Antarctic winter, without eating for weeks. Today, many penguin species are threatened by warming oceans, melting sea ice and overfishing."],
  [w("superb","adjective","/suːˈpɝːb/","極好的","of excellent quality","a superb meal","superb swimmers 一流的泳者。"),
   w("stiff","adjective","/stɪf/","硬的","hard and not easy to bend","stiff paper","stiff flippers 硬鰭。"),
   w("flipper","noun","/ˈflɪp.ɚ/","鰭狀肢","a flat arm used by sea animals for swimming","a seal's flippers","flippers 鰭狀肢。"),
   w("dive","verb","/daɪv/","潛水","to go down into water","dive into the sea","dive hundreds of meters 潛到數百公尺。"),
   w("hemisphere","noun","/ˈhem.ɪ.sfɪr/","半球","one half of the Earth","the Southern Hemisphere","the Southern Hemisphere 南半球。"),
   w("tough","adjective","/tʌf/","艱難的","difficult","a tough job","the toughest lives 最艱苦的生活。"),
   w("threaten","verb","/ˈθret.ən/","威脅","to be likely to harm something","Pollution threatens wildlife.","are threatened by… 受到…威脅。")],
  [gr("almost all of them","幾乎全部。","almost all of them live in the Southern Hemisphere"),
   gr("one of the + 最高級 + 複數名詞","最…之一。","Emperor penguins have one of the toughest lives on Earth."),
   gr("without + V-ing","沒有…。","without eating for weeks")],
  [q("What have penguins' wings become?","Stiff flippers for swimming","Long feathers for flying","Legs for running"),
   q("Where do almost all penguins live?","In the Southern Hemisphere","In the Arctic","In deserts"),
   q("What do male emperor penguins do in winter?","Keep the egg warm on their feet","Fly north","Build nests in trees")]),
 L("How Paper Changed the World", "紙如何改變世界", [
   "Before paper became common, people wrote on materials such as bamboo, silk, clay and animal skins, which were heavy or expensive. Paper made from plant fibers was developed in ancient China, and an official named Cai Lun is traditionally credited with improving the method around 2,000 years ago.",
   "Over many centuries, papermaking spread along trade routes to the Middle East and then to Europe. Combined with the printing press, cheap paper made books far more affordable and helped knowledge spread faster than ever before.",
   "Most paper today is made from wood pulp. Recycling paper saves trees, water and energy, but paper fibers become shorter each time they are recycled, so they can only be reused a limited number of times."],
  [w("material","noun","/məˈtɪr.i.əl/","材料","a substance used to make things","building materials","materials such as… 像…這類材料。"),
   w("fiber","noun","/ˈfaɪ.bɚ/","纖維","a thin thread from a plant or animal","plant fibers","plant fibers 植物纖維。"),
   w("official","noun","/əˈfɪʃ.əl/","官員","a person with a position in government","a government official","an official named… 一位名叫…的官員。"),
   w("method","noun","/ˈmeθ.əd/","方法","a way of doing something","a teaching method","improving the method 改良方法。"),
   w("century","noun","/ˈsen.tʃɚ.i/","世紀","a period of 100 years","the 21st century","many centuries 許多世紀。"),
   w("affordable","adjective","/əˈfɔːr.də.bəl/","負擔得起的","not too expensive","affordable housing","far more affordable 便宜許多。"),
   w("pulp","noun","/pʌlp/","紙漿","a soft wet mass of wood used to make paper","wood pulp","wood pulp 木漿。")],
  [gr("be credited with + V-ing","被認為有…的功勞。","an official named Cai Lun is traditionally credited with improving the method"),
   gr("Combined with…","過去分詞片語：與…結合。","Combined with the printing press, cheap paper made books far more affordable"),
   gr("each time","每次…。","paper fibers become shorter each time they are recycled")],
  [q("Who is traditionally credited with improving papermaking?","Cai Lun","Gutenberg","Confucius"),
   q("What helped books become more affordable?","Cheap paper combined with the printing press","Stone tablets","Silk"),
   q("Why can paper only be recycled a limited number of times?","Its fibers get shorter","It turns into plastic","It becomes too heavy")]),
 L("Relationships Need Exercise Too", "人際關係也需要鍛鍊", [
   "Robert Waldinger directs the Harvard Study of Adult Development, which has followed people's lives for more than 80 years. In this later talk, he returns to the study's central finding: people with warmer relationships tend to be happier and healthier as they grow older.",
   "Waldinger compares relationships to muscles. Just as our bodies need regular exercise, our connections with others need attention, or they slowly weaken. He calls this idea \"social fitness\".",
   "The good news is that the steps can be very small. He encourages listeners to reach out to someone they have lost touch with, ask a colleague a real question, or simply put down their phone and listen. Small actions, repeated often, can keep important relationships strong."],
  [w("central","adjective","/ˈsen.trəl/","核心的","main or most important","the central idea","central finding 核心發現。"),
   w("compare","verb","/kəmˈper/","把…比作","to say that something is similar to something else","compare life to a journey","compare A to B 把 A 比作 B。"),
   w("attention","noun","/əˈten.ʃən/","關注","care and interest given to something","pay attention","need attention 需要用心經營。"),
   w("weaken","verb","/ˈwiː.kən/","變弱","to become less strong","The storm weakened.","weak + -en 變動詞。"),
   w("fitness","noun","/ˈfɪt.nəs/","健康、適應力","being healthy and strong","physical fitness","social fitness 社交健康。"),
   w("lost touch","phrase (lose touch)","/luːz tʌtʃ/","失去聯絡","to stop communicating with someone","We lost touch after school.","have lost touch with… 和…失聯。"),
   w("colleague","noun","/ˈkɑː.liːɡ/","同事","a person you work with","a friendly colleague","ask a colleague 問同事。")],
  [gr("Just as…, …","正如…，…也…。","Just as our bodies need regular exercise, our connections with others need attention"),
   gr("or 表否則","…，否則…。","our connections with others need attention, or they slowly weaken"),
   gr("過去分詞片語 repeated often","= which are repeated often。","Small actions, repeated often, can keep important relationships strong.")],
  [q("What is the study's central finding?","Warmer relationships lead to happier, healthier lives","Money is most important","Exercise is all we need"),
   q("What does Waldinger compare relationships to?","Muscles","Houses","Machines"),
   q("Which small action does he suggest?","Reaching out to someone you lost touch with","Buying expensive gifts","Moving to a new city")]),
]

C1 = [
 L("The Paradox of an Island Rich in Rain", "雨量豐沛之島的矛盾", [
   "Seen from space, Earth looks abundantly watery, yet the overwhelming majority of that water, about 97 percent, is saline. Of the small remainder that is fresh, most is locked in glaciers and ice caps or stored deep underground, leaving a strikingly thin margin readily available for human use.",
   "Taiwan illustrates a paradox. Its annual rainfall is high by global standards, but the island's steep, short rivers rush much of that water to the sea within hours, and rainfall is concentrated in the plum-rain and typhoon seasons.",
   "When typhoons failed to arrive in 2020, the island slid into one of its worst droughts in decades. By the following spring, reservoirs had dwindled to alarmingly low levels, prompting rationing in several regions and difficult trade-offs between farms, households and water-intensive industries.",
   "Globally, agriculture accounts for the lion's share of freshwater withdrawals, which is why the most consequential savings often lie in efficient irrigation and leak-free distribution networks. Household habits matter too, but they work best alongside smarter infrastructure and pricing that reflects water's true scarcity."],
  [w("abundantly","adverb","/əˈbʌn.dənt.li/","豐富地","in large amounts","abundantly clear","abundantly watery 水量充沛。"),
   w("saline","adjective","/ˈseɪ.liːn/","含鹽的","containing salt","saline water","is saline 是鹹水。"),
   w("paradox","noun","/ˈper.ə.dɑːks/","矛盾","a situation that seems impossible because it has opposite features","a strange paradox","illustrates a paradox 說明一個矛盾。"),
   w("dwindle","verb","/ˈdwɪn.dəl/","逐漸減少","to become gradually smaller","Supplies dwindled.","had dwindled 已經減少。"),
   w("rationing","noun","/ˈræʃ.ən.ɪŋ/","配給、限量供應","limiting the amount people can have","water rationing","prompting rationing 導致限水。"),
   w("lion's share","idiom","/ˈlaɪ.ənz ʃer/","最大份","the largest part","the lion's share of the profits","the lion's share of… …的大部分。"),
   w("irrigation","noun","/ˌɪr.əˈɡeɪ.ʃən/","灌溉","supplying water to crops","drip irrigation","efficient irrigation 高效灌溉。"),
   w("scarcity","noun","/ˈsker.sə.t̬i/","稀缺","a situation in which something is not easy to find","water scarcity","true scarcity 真實的稀缺程度。")],
  [gr("過去分詞片語 Seen from space","從太空看（被動分詞構句）。","Seen from space, Earth looks abundantly watery"),
   gr("Of the… that…, most is…","在…之中，大部分是…。","Of the small remainder that is fresh, most is locked in glaciers and ice caps"),
   gr("By the following spring, had + p.p.","到隔年春天之前已經…（過去完成）。","By the following spring, reservoirs had dwindled to alarmingly low levels")],
  [q("What is the 'paradox' of Taiwan's water?","High rainfall but water flows away quickly","No rain at all","Too many reservoirs"),
   q("What led to the drought described in the text?","Typhoons failed to arrive in 2020","Too much rain","An earthquake"),
   q("Where do the most consequential savings often lie, according to the writer?","Efficient irrigation and leak-free networks","Shorter showers only","Building more swimming pools")]),
 L("Masters of Two Worlds", "兩個世界的主人", [
   "Penguins forfeited flight long ago, but evolution compensated generously. Their wings have hardened into rigid flippers, dense bones counteract buoyancy, and streamlined bodies slip through water with remarkable efficiency. Emperor penguins can descend more than 500 meters in pursuit of prey, holding their breath for many minutes.",
   "Contrary to popular imagery, penguins are not exclusively creatures of the ice. Of roughly eighteen species, only a handful breed on Antarctica itself; the rest inhabit sub-Antarctic islands and the coasts of South America, southern Africa, Australia and New Zealand. One species even nests on the equatorial Galápagos.",
   "The emperor penguin's breeding cycle is among the most grueling in nature. Through the Antarctic winter, males incubate a single egg on their feet, huddling together against ferocious winds and fasting for weeks until the females return from the sea.",
   "That dependence on a stable environment leaves many species precarious. Shrinking sea ice threatens the platforms emperors need to raise chicks, while warming waters, overfishing and pollution disrupt the food webs on which all penguins rely."],
  [w("forfeit","verb","/ˈfɔːr.fɪt/","喪失、放棄","to lose something as a result of something else","forfeit the right","forfeited flight 失去飛行能力。"),
   w("compensate","verb","/ˈkɑːm.pən.seɪt/","補償","to make up for something lost","compensate for the loss","compensated generously 給了慷慨的補償。"),
   w("buoyancy","noun","/ˈbɔɪ.ən.si/","浮力","the ability to float","the buoyancy of salt water","counteract buoyancy 抵銷浮力。"),
   w("streamlined","adjective","/ˈstriːm.laɪnd/","流線型的","shaped to move easily through air or water","a streamlined car","streamlined bodies 流線型身體。"),
   w("exclusively","adverb","/ɪkˈskluː.sɪv.li/","僅僅、專門地","only","exclusively for members","not exclusively 不全然是。"),
   w("grueling","adjective","/ˈɡruː.ə.lɪŋ/","艱辛的","very difficult and tiring","a grueling race","among the most grueling 最艱苦之一。"),
   w("incubate","verb","/ˈɪŋ.kjə.beɪt/","孵（蛋）","to keep eggs warm until they hatch","Birds incubate their eggs.","incubate a single egg 孵一顆蛋。"),
   w("precarious","adjective","/prɪˈker.i.əs/","岌岌可危的","not safe or stable","a precarious position","leaves many species precarious 讓許多物種處境危險。")],
  [gr("Contrary to…","與…相反。","Contrary to popular imagery, penguins are not exclusively creatures of the ice."),
   gr("only a handful…; the rest…","只有少數…；其餘…（分號對比）。","only a handful breed on Antarctica itself; the rest inhabit sub-Antarctic islands"),
   gr("介系詞 + which","on which = 企鵝所依賴的。","the food webs on which all penguins rely")],
  [q("How have penguins' bodies adapted to swimming?","Rigid flippers, dense bones and streamlined bodies","Light bones and long wings","Webbed wings for flying"),
   q("What popular image does the writer correct?","That all penguins live on the ice","That penguins can fly","That penguins eat fish"),
   q("Why are emperor penguins threatened by shrinking sea ice?","They need it to raise their chicks","They eat ice","It makes them too warm")]),
 L("A Material We Barely Notice", "我們幾乎沒注意到的材料", [
   "Paper is so ubiquitous that it has become almost invisible, yet for most of recorded history writing depended on far less convenient surfaces: clay tablets, bamboo strips, costly silk or parchment made from animal skin. Each constrained how much could be written and who could afford to do so.",
   "The breakthrough came in China. Fragments of early paper predate him, but Cai Lun, an official of the Han court, is traditionally credited around 105 CE with refining a method of pulping plant fibers into thin, durable sheets.",
   "The technique remained a closely held advantage for centuries before spreading westward along trade routes to the Islamic world, where paper mills flourished, and eventually to Europe. Paired with movable-type printing, abundant paper made books cheap enough to fuel mass literacy, the circulation of scientific ideas and the spread of religious and political debate.",
   "The shift to wood pulp in the nineteenth century made paper cheaper still, at considerable cost to forests. Recycling now recovers much of what we use, though not indefinitely: each cycle shortens the fibers, which is why recycled paper typically requires an infusion of fresh pulp."],
  [w("invisible","adjective","/ɪnˈvɪz.ə.bəl/","看不見的","impossible to see or notice","invisible to the eye","almost invisible 幾乎被忽略。"),
   w("parchment","noun","/ˈpɑːrtʃ.mənt/","羊皮紙","writing material made from animal skin","an old parchment","parchment made from animal skin 獸皮製的羊皮紙。"),
   w("constrain","verb","/kənˈstreɪn/","限制","to limit something","constrained by money","constrained how much… 限制了能寫多少。"),
   w("predate","verb","/ˌpriːˈdeɪt/","早於","to exist before something else","The church predates the town.","predate him 早於他。"),
   w("durable","adjective","/ˈdʊr.ə.bəl/","耐用的","able to last a long time","durable materials","durable sheets 耐用的紙張。"),
   w("literacy","noun","/ˈlɪt̬.ɚ.ə.si/","識字能力","the ability to read and write","adult literacy","mass literacy 大眾識字。"),
   w("abundant","adjective","/əˈbʌn.dənt/","大量的","existing in large quantities","abundant resources","abundant paper 大量的紙。"),
   w("infusion","noun","/ɪnˈfjuː.ʒən/","注入、添加","the addition of something new","an infusion of cash","an infusion of fresh pulp 加入新紙漿。")],
  [gr("so… that…","如此普遍以致於…。","Paper is so ubiquitous that it has become almost invisible"),
   gr("過去分詞片語 Paired with…","與…搭配時（被動分詞構句）。","Paired with movable-type printing, abundant paper made books cheap enough to fuel mass literacy"),
   gr("enough to + V","足以…。","made books cheap enough to fuel mass literacy")],
  [q("Why did earlier writing surfaces matter?","They limited how much could be written and by whom","They were all free","They lasted forever"),
   q("What does the writer say about Cai Lun?","He is traditionally credited with refining papermaking","He invented writing","He built the first printing press"),
   q("Why can paper not be recycled indefinitely?","Each cycle shortens the fibers","It becomes plastic","It loses its color")]),
 L("The Practice of Social Fitness", "社交體能的練習", [
   "Robert Waldinger has spent much of his career overseeing the Harvard Study of Adult Development, an investigation now spanning more than eight decades and, more recently, the children of its original participants. In this later talk, he revisits the study's most robust conclusion: the quality of our relationships is among the strongest predictors of health and happiness as we age.",
   "What Waldinger adds here is a practical metaphor. Relationships, he suggests, behave like muscles. Neglect them and they atrophy; tend to them and they strengthen. Just as we accept that physical fitness requires ongoing effort, he argues that we should cultivate what he calls social fitness.",
   "The framing is deliberately modest. Rather than demanding grand gestures, he points to small acts sustained over time: rekindling a lapsed friendship, asking a coworker a question that invites a genuine answer, giving someone our undivided attention.",
   "Part of the talk's appeal is that it counters a pervasive myth, namely that connection should happen effortlessly. Waldinger's research suggests the opposite: lasting bonds are maintained deliberately, and it is never too late to begin."],
  [w("oversee","verb","/ˌoʊ.vɚˈsiː/","監督、主持","to be in charge of work or people","oversee a project","overseeing 動名詞。"),
   w("investigation","noun","/ɪnˌves.təˈɡeɪ.ʃən/","調查、研究","a careful study of something","a scientific investigation","an investigation spanning… 一項橫跨…的研究。"),
   w("metaphor","noun","/ˈmet̬.ə.fɔːr/","比喻","describing something by comparing it to something else","a powerful metaphor","a practical metaphor 實用的比喻。"),
   w("neglect","verb","/nɪˈɡlekt/","忽略","to not give enough care to something","neglect your health","Neglect them and… 忽略它們，就會…。"),
   w("cultivate","verb","/ˈkʌl.t̬ə.veɪt/","培養","to develop something through effort","cultivate friendships","cultivate social fitness 培養社交體能。"),
   w("rekindle","verb","/ˌriːˈkɪn.dəl/","重新點燃","to make a feeling or relationship start again","rekindle a romance","rekindling a friendship 重拾友誼。"),
   w("undivided","adjective","/ˌʌn.dɪˈvaɪ.dɪd/","專一的、全部的","complete and not shared","undivided attention","undivided attention 全神貫注。"),
   w("pervasive","adjective","/pɚˈveɪ.sɪv/","普遍的","present everywhere","a pervasive smell","a pervasive myth 普遍的迷思。")],
  [gr("祈使句 + and 表條件","Neglect them and… = 如果忽略它們，就…。","Neglect them and they atrophy; tend to them and they strengthen."),
   gr("Rather than + V-ing","與其…不如…。","Rather than demanding grand gestures, he points to small acts sustained over time"),
   gr("namely","也就是。","it counters a pervasive myth, namely that connection should happen effortlessly")],
  [q("What metaphor does Waldinger use for relationships?","Muscles that weaken without use","Houses that need painting","Plants that need sun"),
   q("What kind of actions does he recommend?","Small acts sustained over time","Grand romantic gestures","Moving abroad"),
   q("What myth does the talk challenge?","That connection should happen effortlessly","That exercise is healthy","That studies take time")]),
]
